class Solution {

    public boolean isValid(String s) {
        String prev = null;
        while (!s.equals(prev)) {
            // repeat until no change
            prev = s;
            s = s.replace("()", "").replace("[]", "").replace("{}", "");
        }
        return s.isEmpty();
    }
}

