class Solution {

    public int evalRPN(String[] tokens) {
        List<String> list = new ArrayList<>(Arrays.asList(tokens));
        while (list.size() > 1) {
            int i = 0;
            while (!isOp(list.get(i))) i++; // first operator
            int a = Integer.parseInt(list.get(i - 2));
            int b = Integer.parseInt(list.get(i - 1));
            int res = apply(a, b, list.get(i));
            list.set(i - 2, String.valueOf(res)); // replace 3 tokens with 1
            list.remove(i);
            list.remove(i - 1);
        }
        return Integer.parseInt(list.get(0));
    }

    private boolean isOp(String t) {
        return (
            t.equals("+") ||
            t.equals("-") ||
            t.equals("*") ||
            t.equals("/")
        );
    }

    private int apply(int a, int b, String op) {
        switch (op) {
            case "+":
                return a + b;
            case "-":
                return a - b;
            case "*":
                return a * b;
            default:
                return a / b; // Java truncates toward zero
        }
    }
}

