        const a = Number(list[i - 2]),
            b = Number(list[i - 1]);
        let res;
        if (list[i] === "+") res = a + b;
        else if (list[i] === "-") res = a - b;
        else if (list[i] === "*") res = a * b;
        else res = Math.trunc(a / b); // truncate toward zero
        list.splice(i - 2, 3, String(res)); // replace 3 tokens with 1
    }
    return Number(list[0]);
};

