class Solution {

    public int carFleet(int target, int[] position, int[] speed) {
        int n = position.length;
        double[] time = new double[n];
        for (int i = 0; i < n; i++) time[i] =
            (double) (target - position[i]) / speed[i];
        int fleets = 0;
        for (int i = 0; i < n; i++) {
            boolean blocked = false;
            for (int j = 0; j < n; j++) {
                // a car ahead that is slower (or equal) catches car i
                if (position[j] > position[i] && time[j] >= time[i]) {
                    blocked = true;
                    break;
                }
            }

            if (!blocked) fleets++;
        }
        return fleets;
    }
}

