class Solution {

    public int sumSubarrayMins(int[] arr) {
        final int MOD = 1_000_000_007;
        int n = arr.length;
        int[] left = new int[n],
            right = new int[n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && arr[st.peek()] >= arr[i]) st.pop();
            left[i] = st.isEmpty() ? i + 1 : i - st.peek(); // prev strictly smaller
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.isEmpty() && arr[st.peek()] > arr[i]) st.pop();
            right[i] = st.isEmpty() ? n - i : st.peek() - i; // next smaller or equal
            st.push(i);
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            // long avoids overflow: arr[i] * left * right can exceed 2^31
            sum =
                (sum + (((long) arr[i] * left[i]) % MOD) * right[i]) %
                MOD;
        }
        return (int) sum;
    }
}

