class Solution {

    public long subArrayRanges(int[] nums) {
        return sum(nums, true) - sum(nums, false);
    }

    // sum of subarray maxima (isMax) or minima (!isMax)
    private long sum(int[] a, boolean isMax) {
        int n = a.length;
        int[] left = new int[n],
            right = new int[n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (
                    !st.isEmpty() &&
                    (isMax
                        ? a[st.peek()] <= a[i]
                        : a[st.peek()] >= a[i])
                )
                st.pop();
            left[i] = st.isEmpty() ? i + 1 : i - st.peek();
            st.push(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (
                    !st.isEmpty() &&
                    (isMax ? a[st.peek()] < a[i] : a[st.peek()] > a[i])
                )
                st.pop();
            right[i] = st.isEmpty() ? n - i : st.peek() - i;
            st.push(i);
        }
        long total = 0;
        for (int i = 0; i < n; i++) total +=
            (long) a[i] * left[i] * right[i]; // long: avoids overflow
        return total;
    }
}

