            while (st.length && worse(a[st[st.length - 1]], a[i]))
                st.pop();

            left[i] = st.length ? i - st[st.length - 1] : i + 1;
            st.push(i);
        }
        st = [];
        for (let i = n - 1; i >= 0; i--) {
            while (st.length && worseStrict(a[st[st.length - 1]], a[i]))
                st.pop();
            right[i] = st.length ? st[st.length - 1] - i : n - i;
            st.push(i);
        }
        let total = 0;
        for (let i = 0; i < n; i++) total += a[i] * left[i] * right[i];
        return total;
    };
    return sum(nums, true) - sum(nums, false);
};

