class Solution {

    public String removeKdigits(String num, int k) {
        StringBuilder st = new StringBuilder(); // used as a stack
        for (char d : num.toCharArray()) {
            while (
                k > 0 &&
                st.length() > 0 &&
                st.charAt(st.length() - 1) > d
            ) {
                st.deleteCharAt(st.length() - 1); // bigger digit before smaller: drop it
                k--;
            }
            st.append(d);
        }
        st.setLength(Math.max(0, st.length() - k)); // leftover removals from the end
        int start = 0;
        while (start < st.length() && st.charAt(start) == '0') start++;
        return start == st.length() ? "0" : st.substring(start);
    }
}

