class Solution {

    public int maximalRectangle(char[][] matrix) {
        int c = matrix[0].length,
            best = 0;
        int[] heights = new int[c];
        for (char[] row : matrix) {
            for (int j = 0; j < c; j++) heights[j] =
                row[j] == '1' ? heights[j] + 1 : 0;
            best = Math.max(best, largestRectangle(heights)); // histogram for this row
        }
        return best;
    }

    private int largestRectangle(int[] h) {
        int n = h.length,
            best = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i <= n; i++) {
            int cur = i == n ? 0 : h[i];
            while (!stack.isEmpty() && h[stack.peek()] >= cur) {
                int height = h[stack.pop()];
                int left = stack.isEmpty() ? -1 : stack.peek();

                best = Math.max(best, height * (i - left - 1));
            }
            stack.push(i);
        }
        return best;
    }
}

