class Solution {

    public int celebrity(int[][] mat) {
        int n = mat.length;
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) st.push(i);
        while (st.size() > 1) {
            int a = st.pop(),
                b = st.pop();
            st.push(mat[a][b] == 1 ? b : a); // keep the one not ruled out
        }
        int c = st.pop();
        for (int j = 0; j < n; j++) {
            if (j != c && (mat[c][j] == 1 || mat[j][c] == 0)) return -1; // verify
        }
        return c;
    }
}

