class LFUCache {

    private final int capacity;
    private int clock = 0;
    private final Map<Integer, int[]> map = new HashMap<>(); // key -> {value, freq, time}

    public LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        int[] e = map.get(key);
        if (e == null) return -1;
        e[1]++;

        e[2] = ++clock;
        return e[0];
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        int[] e = map.get(key);
        if (e != null) {
            e[0] = value;
            e[1]++;
            e[2] = ++clock;
            return;
        }
        if (map.size() == capacity) {
            int victim = -1;
            int[] worst = null;
            for (Map.Entry<Integer, int[]> en : map.entrySet()) {
                // O(n) scan
                int[] v = en.getValue();
                if (
                    worst == null ||
                    v[1] < worst[1] ||
                    (v[1] == worst[1] && v[2] < worst[2])
                ) {
                    worst = v;
                    victim = en.getKey();
                }
            }
            map.remove(victim);
        }
        map.put(key, new int[] { value, 1, ++clock });
    }
}

