        if (this.map.size === this.capacity) {
            let victim = null,
                worst = null;
            for (const [k, v] of this.map) {
                // O(n) scan
                if (
                    !worst ||
                    v.freq < worst.freq ||
                    (v.freq === worst.freq && v.time < worst.time)
                ) {
                    worst = v;
                    victim = k;
                }
            }
            this.map.delete(victim);
        }
        this.map.set(key, { value, freq: 1, time: ++this.clock });
    }
}

