class LFUCache {
    private final int capacity;
    private int minFreq = 0;
    private final Map<Integer, int[]> vals = new HashMap<>();                           // key -> {value, freq}
    private final Map<Integer, LinkedHashSet<Integer>> buckets = new HashMap<>(); // freq -> keys, oldest
    first

    public LFUCache(int capacity) { this.capacity = capacity; }

    public int get(int key) {
        int[] e = vals.get(key);
        if (e == null) return -1;
        touch(key, e);
        return e[0];
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        int[] e = vals.get(key);
        if (e != null) { e[0] = value; touch(key, e); return; }
        if (vals.size() == capacity) {
            LinkedHashSet<Integer> set = buckets.get(minFreq);
            int victim = set.iterator().next();             // least recently used among least frequent
            set.remove(victim);
            if (set.isEmpty()) buckets.remove(minFreq);
            vals.remove(victim);
        }
        vals.put(key, new int[]{value, 1});
        buckets.computeIfAbsent(1, f -> new LinkedHashSet<>()).add(key);
        minFreq = 1;                                         // a new key always has the lowest freq
    }

    private void touch(int key, int[] e) {
        int f = e[1];
        LinkedHashSet<Integer> set = buckets.get(f);
        set.remove(key);
        if (set.isEmpty()) {
            buckets.remove(f);
            if (minFreq == f) minFreq = f + 1;              // the min bucket just emptied
        }
        e[1] = f + 1;
        buckets.computeIfAbsent(f + 1, x -> new LinkedHashSet<>()).add(key);        // newest at the end

    }
}

