class LFUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.minFreq = 0;
        this.vals = new Map(); // key -> {value, freq}
        this.buckets = new Map(); // freq -> Set of keys (insertion = recency order)
    }
    #touch(key, e) {
        const f = e.freq,
            set = this.buckets.get(f);
        set.delete(key);
        if (set.size === 0) {
            this.buckets.delete(f);
            if (this.minFreq === f) this.minFreq = f + 1; // the min bucket just emptied
        }
        e.freq = f + 1;
        if (!this.buckets.has(f + 1))
            this.buckets.set(f + 1, new Set());
        this.buckets.get(f + 1).add(key); // newest at the end
    }
    get(key) {
        const e = this.vals.get(key);
        if (!e) return -1;
        this.#touch(key, e);
        return e.value;
    }
    put(key, value) {
        if (this.capacity === 0) return;
        const e = this.vals.get(key);
        if (e) {
            e.value = value;
            this.#touch(key, e);
            return;
        }
        if (this.vals.size === this.capacity) {
            const set = this.buckets.get(this.minFreq);
            const victim = set.values().next().value; // oldest key in the lowest bucket
            set.delete(victim);
            if (set.size === 0) this.buckets.delete(this.minFreq);
            this.vals.delete(victim);
        }
        this.vals.set(key, { value, freq: 1 });
        if (!this.buckets.has(1)) this.buckets.set(1, new Set());
        this.buckets.get(1).add(key);
        this.minFreq = 1; // a new key always has the lowest freq
    }
}
